def make_client_user(
    session: Session,
    *,
    firebase_uid: str = "uid-client-1",
    email: str | None = "client@example.com",
    status: AccountStatus = AccountStatus.ACTIVE,
    with_profile: bool = True,
    authorized_by: str | None = None,
) -> User:
    """Seeds a users(portal=client) row (+ optional client_profiles row) directly
    via the ORM at the given AccountStatus, bypassing UserRepository entirely."""
    user = User(
        id=uuid.uuid4(),
        firebase_uid=firebase_uid,
        email=email,
        portal=Portal.CLIENT,
        status=status,
        authorized_by=authorized_by,
    )
    session.add(user)
    session.flush()
    if with_profile:
        session.add(ClientProfile(user_id=user.id, name="Test Client"))
    session.commit()
    session.refresh(user)
    return user


def make_admin_user(
    session: Session,
    *,
    firebase_uid: str = "uid-admin-1",
    email: str | None = "admin@example.com",
    role: AdminRole = AdminRole.ADMIN,
    status: AccountStatus = AccountStatus.ACTIVE,
    with_profile: bool = True,
    authorized_by: str | None = None,
) -> User:
    """Seeds a users(portal=admin) row (+ optional admin_profiles row) directly
    via the ORM at the given AccountStatus/AdminRole, bypassing UserRepository."""
    user = User(
        id=uuid.uuid4(),
        firebase_uid=firebase_uid,
        email=email,
        portal=Portal.ADMIN,
        status=status,
        authorized_by=authorized_by,
    )
    session.add(user)
    session.flush()
    if with_profile:
        session.add(AdminProfile(user_id=user.id, role=role))
    session.commit()
    session.refresh(user)
    # BE-2: load admin_profile onto the instance now -- some callers (e.g.
    # test_be5_access_control_resolves_from_db.py) close `session` right after
    # this returns, and an already-loaded attribute is never lazy-loaded on the
    # detached instance.
    session.refresh(user, attribute_names=["admin_profile"])
    return user


